package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.DpopBoundAccessTokensVO;

class DpopBoundAccessTokensValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of dpop bound access tokens of oauth client")
  void test_dpop_bound_access_tokens_value_holder_assign_plain_value() {
    Object holder = new Object();
    DpopBoundAccessTokensValueHolder<Object> value = new DpopBoundAccessTokensValueHolder<>(holder);
    Assertions.assertSame(holder, value.dpopBoundAccessTokens(true),
        "Setters must return the holder");
    Assertions.assertTrue(value.getDpopBoundAccessTokensValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(true, value.getDpopBoundAccessTokens().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of dpop bound access tokens of oauth client")
  void test_dpop_bound_access_tokens_value_holder_assign_value_object() {
    Object holder = new Object();
    DpopBoundAccessTokensValueHolder<Object> value = new DpopBoundAccessTokensValueHolder<>(holder);
    DpopBoundAccessTokensVO vo = DpopBoundAccessTokensVO.from(true);
    Assertions.assertFalse(value.getDpopBoundAccessTokensValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.dpopBoundAccessTokens(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getDpopBoundAccessTokensValue().orElseThrow());
    Assertions.assertSame(holder, value.dpopBoundAccessTokens(Optional.empty()));
    Assertions.assertFalse(value.getDpopBoundAccessTokensValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.dpopBoundAccessTokens(Optional.of(vo)));
    Assertions.assertSame(vo, value.getDpopBoundAccessTokensValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of dpop bound access tokens of oauth client against the original")
  void test_dpop_bound_access_tokens_value_holder_read() {
    Object holder = new Object();
    DpopBoundAccessTokensValueHolder<Object> value = new DpopBoundAccessTokensValueHolder<>(holder);
    DpopBoundAccessTokensVO vo = DpopBoundAccessTokensVO.from(true);
    DpopBoundAccessTokensVO other = DpopBoundAccessTokensVO.from(true);
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getDpopBoundAccessTokensValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readDpopBoundAccessTokens(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readDpopBoundAccessTokens(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.dpopBoundAccessTokens(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readDpopBoundAccessTokens(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readDpopBoundAccessTokens(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of dpop bound access tokens of oauth client")
  void test_dpop_bound_access_tokens_value_holder_unset() {
    Object holder = new Object();
    DpopBoundAccessTokensValueHolder<Object> value = new DpopBoundAccessTokensValueHolder<>(holder);
    DpopBoundAccessTokensVO vo = DpopBoundAccessTokensVO.from(true);
    value.dpopBoundAccessTokens(vo);
    Assertions.assertSame(holder,
        value.unsetDpopBoundAccessTokensIfMatches("dpopBoundAccessTokens_other"));
    Assertions.assertTrue(value.getDpopBoundAccessTokensValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder,
        value.unsetDpopBoundAccessTokensIfMatches("dpopBoundAccessTokens"));
    Assertions.assertFalse(value.getDpopBoundAccessTokensValue().isPresent(),
        "The field name must clear the value");
    value.dpopBoundAccessTokens(vo);
    Assertions.assertSame(holder, value.unsetDpopBoundAccessTokens());
    Assertions.assertFalse(value.getDpopBoundAccessTokensValue().isPresent(),
        "Unset must clear the value");
  }
}
